  const seen = new Set();
  for (const id of ids) {
    if (!nonEmptyString(id)) add('malformed-id', `${label}: every entry needs a non-empty id`);
    else if (seen.has(id)) add('duplicate-id', `${label}: id "${id}" appears more than once`);
